/// <summary>
/// Table Extension
/// </summary>
[ExtensionOf(tableStr(METCustTable))]
Public final class METCustTableMetPriceEng_Extension
{
}

Method.Source:
    //TODO: Move code to MEtcash model when Metcash Price Engine model is removed
    /// <summary>
    /// CoC Update
    /// </summary>
    public void update()
    {
        boolean         fieldUpdated = false;
        METCustTable    metCustTableOrig = this.orig();

        if(this.CustOperGroupId != metCustTableOrig.CustOperGroupId
        || this.CBStore         != metCustTableOrig.CBStore
        || this.CBCTStopDate    != metCustTableOrig.CBCTStopDate)
        {
            fieldUpdated = true;
        }
        
        next update();

        if(fieldUpdated)
        {
            METPriceChangeEventCustomer::metProcessTrackChange(this.custTable());
        }
    }
